create table if not exists public.study_groups(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,description text not null default '',invite_code text not null unique,created_at timestamptz not null default now());
create index if not exists study_groups_owner_idx on public.study_groups(owner_id);
create table if not exists public.study_group_members(group_id uuid not null references public.study_groups(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','member')),joined_at timestamptz not null default now(),primary key(group_id,user_id));
create index if not exists study_group_members_user_idx on public.study_group_members(user_id,group_id);
create table if not exists public.study_group_posts(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.study_groups(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,title text not null,content text not null default '',link_url text,created_at timestamptz not null default now());
create index if not exists study_group_posts_group_created_idx on public.study_group_posts(group_id,created_at desc);
alter table public.study_groups enable row level security;alter table public.study_group_members enable row level security;alter table public.study_group_posts enable row level security;
revoke all on public.study_groups,public.study_group_members,public.study_group_posts from anon;grant select,insert,update,delete on public.study_groups,public.study_group_members,public.study_group_posts to authenticated;
create policy "Members can view study groups" on public.study_groups for select to authenticated using(owner_id=(select auth.uid()) or exists(select 1 from public.study_group_members m where m.group_id=id and m.user_id=(select auth.uid())));
create policy "Students create their own study groups" on public.study_groups for insert to authenticated with check(owner_id=(select auth.uid()));
create policy "Owners update their study groups" on public.study_groups for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy "Owners delete their study groups" on public.study_groups for delete to authenticated using(owner_id=(select auth.uid()));
create policy "Members can view group membership" on public.study_group_members for select to authenticated using(user_id=(select auth.uid()));
create policy "Group owners add initial membership" on public.study_group_members for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.study_groups g where g.id=group_id and g.owner_id=(select auth.uid())));
create policy "Members can leave groups" on public.study_group_members for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.study_groups g where g.id=group_id and g.owner_id=(select auth.uid())));
create policy "Group members read posts" on public.study_group_posts for select to authenticated using(exists(select 1 from public.study_group_members m where m.group_id=study_group_posts.group_id and m.user_id=(select auth.uid())));
create policy "Group members create posts" on public.study_group_posts for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.study_group_members m where m.group_id=study_group_posts.group_id and m.user_id=(select auth.uid())));
create policy "Authors or owners delete posts" on public.study_group_posts for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.study_groups g where g.id=group_id and g.owner_id=(select auth.uid())));
